Assuming React. Debounce via `setTimeout` in `useEffect`; cleanup cancels the pending timer on each keystroke. `AbortController` drops stale in-flight responses, so slow old requests can't overwrite newer results.

```jsx
import { useEffect, useState } from "react";

function Search() {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);

  useEffect(() => {
    if (!query.trim()) { setResults([]); return; }

    const controller = new AbortController();
    const timer = setTimeout(async () => {
      try {
        const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, {
          signal: controller.signal,
        });
        setResults(await res.json());
      } catch (e) {
        if (e.name !== "AbortError") console.error(e);
      }
    }, 300);

    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [query]);

  return (
    <>
      <input
        type="search"
        aria-label="Search"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />
      <ul>{results.map((r) => <li key={r.id}>{r.name}</li>)}</ul>
    </>
  );
}
```

Vanilla JS equivalent:

```js
let timer, controller;
input.addEventListener("input", (e) => {
  clearTimeout(timer);
  timer = setTimeout(async () => {
    controller?.abort();
    controller = new AbortController();
    try {
      const res = await fetch(`/api/search?q=${encodeURIComponent(e.target.value)}`, { signal: controller.signal });
      render(await res.json());
    } catch (err) {
      if (err.name !== "AbortError") console.error(err);
    }
  }, 300);
});
```

